static bool chat_weather_tool_enabled(void)
{
  char val[16];
  size_t i;

  val[0] = '\0';

  /* claw_config_get() 失败时不动缓冲区，所以先自己置空 */

  if (claw_config_get(MIMO_CFG_KEY_WEATHER_TOOL, val, sizeof(val)) != OK)
    {
      return false;
    }

  trim_whitespace(val);

  /* 先折成小写再比：不引 strings.h，不动 strcasecmp，只处理 ASCII 字母
   * （这几个字面量里也没有非 ASCII） */

  for (i = 0; val[i] != '\0'; i++)
    {
      if (val[i] >= 'A' && val[i] <= 'Z')
        {
          val[i] = (char)(val[i] - 'A' + 'a');
        }
    }

  return strcmp(val, "1") == 0 || strcmp(val, "true") == 0
         || strcmp(val, "on") == 0;
}

