static bool chat_config_flag_on(const char *key, bool missing_default)
{
  char val[16];
  size_t i;

  val[0] = '\0';

  if (claw_config_get(key, val, sizeof(val)) != OK)
    {
      return missing_default;
    }

  trim_whitespace(val);

  /* 先折成小写再比：不引 strings.h，不动 strcasecmp，只处理 ASCII 字母
