/****************************************************************************
 * Name: chat_tool_add_reminder
 *
 * Description:
 *   执行 add_reminder 工具：从 arguments 里取 time / title，校验/规范化时间，
 *   再交给 app 注册进来的 mimo_reminder_hook_t 落地（robot_ui 会写进提醒列表
 *   并重挂 RTC 闹钟）。
 *
 *   **任何失败都不返回负值**，而是把中文原因写进 out 当工具结果喂回模型，
 *   让模型自己跟用户解释（"提醒列表满了"这种事模型说出来比界面弹窗自然）。
 *   只有 out 装不下这种编程错误才回 -ENOMEM。
 *
 * Returned Value:
 *   OK on success（out 里有工具结果文本）; -ENOMEM。
 *
 ****************************************************************************/

static int chat_tool_add_reminder(const char *args_escaped, char *out,
                                  size_t out_cap)
{
  char plain[640];
  char time_raw[32];
  char title_raw[256];
  char title[REMINDER_TITLE...]  -- can't; use 64 hard: `char title[64]`
  char hhmm[8];
  const char *val;
  size_t n;
  int hh;
  int mm;
  int ret;
  bool truncated = false;

  /* arguments 是"JSON 里的字符串"，先反转义出真正的 JSON 文本 */

  n = json_unescape(args_escaped, strlen(args_escaped), plain, sizeof(plain) - 1);
  plain[n] = '\0';

  val = json_find_string(plain, "time", &n);
  if (val == NULL || n == 0)
    {
      snprintf(out, out_cap, "调用失败：缺少 time 参数。请用 24 小时制的 HH:MM，"
                             "例如 08:00，重新调用一次。");
      return OK;
    }

  n = json_unescape(val, n, time_raw, sizeof(time_raw) - 1);
  time_raw[n] = '\0';
  trim_whitespace(time_raw);

  val = json_find_string(plain, "title", &n);
  if (val == NULL || n == 0)
    {
      snprintf(out, out_cap, "调用失败：缺少 title 参数。请用简短中文写清楚"
                             "提醒做什么，例如 吃药，重新调用一次。");
      return OK;
    }

  n = json_unescape(val, n, title_raw, sizeof(title_raw) - 1);
  title_raw[n] = '\0';
  trim_whitespace(title_raw);

  /* 时间必须是 24 小时制 HH:MM：模型偶尔会传 "8点" / "晚上八点"，这时**不要
   * 自己猜**（猜错了就是到点不响），让它自己换算重试。 */

  if (sscanf(time_raw, "%d:%d", &hh, &mm) != 2 || hh < 0 || hh > 23
      || mm < 0 || mm > 59)
    {
      snprintf(out, out_cap, "调用失败：time 必须是 24 小时制的 HH:MM，"
                             "收到的是“%.40s”。请把口语时间换算好再调用一次，"
                             "例如下午三点写成 15:00。", time_raw);
      return OK;
    }

  /* 提醒列表每条标题只有 64 字节，按整字截到 20 字（多出来的部分模型多半
   * 是画蛇添足的修饰，截了比让 hook 拒收好） */

  tts_truncate(title_raw, title, sizeof(title), MIMO_REMINDER_TITLE_CHARS, &truncated);

  snprintf(hhmm, sizeof(hhmm), "%02d:%02d", hh, mm);

  if (s_reminder_hook == NULL)
    {
      snprintf(out, out_cap, "调用失败：本机没有可用的提醒功能。");
      return OK;
    }

  ret = s_reminder_hook(hhmm, title);

  if (ret < 0)
    {
      syslog(LOG_WARNING, "[%s] add_reminder(%s, %s) 失败: %d\n", TAG, hhmm,
             title, ret);
      snprintf(out, out_cap, "调用失败：%s 这条提醒没能建起来（错误码 %d）。"
                             "请跟用户说一声，让他稍后再试。", hhmm, ret);
      return OK;
    }

  syslog(LOG_INFO, "[%s] add_reminder 成功: %s %s%s\n", TAG, hhmm, title,
         truncated ? "（标题已截短）" : "");

  snprintf(out, out_cap,
           "已建好：从今天起每天 %s 提醒用户%s。请在回复里复述一遍确认。",
           hhmm, title);

  return OK;
}
