```c
typedef struct {
    int   status;        /* -1 = 不改 */
    int   face;          /* -1 = 不改 */
    char *reply;         /* NULL = 不改；非 NULL 由回调 free */
} ui_msg_t;

static void ui_apply_msg(void *arg)
{
    ui_msg_t *m = (ui_msg_t *)arg;

    if (m->status >= 0) {
        robot_ui_set_status((robot_status_t)m->status);
    }
    if (m->face >= 0) {
        robot_ui_set_face((robot_face_t)m->face);
    }
    if (m->reply != NULL) {
        robot_ui_set_ai_reply(m->reply);
    }

    free(m->reply);
    free(m);
}

/* 非 LVGL 线程用：投递一次界面更新 */
static void ui_post(int status, int face, const char *reply)
{
    ui_msg_t *m = malloc(sizeof(ui_msg_t));

    if (m == NULL) {
        return;
    }

    m->status = status;
    m->face   = face;
    m->reply  = NULL;

    if (reply != NULL) {
        size_t n = strlen(reply) + 1;

        m->reply = malloc(n);
        if (m->reply != NULL) {
            memcpy(m->reply, reply, n);
        }
    }

    if (lv_async_call(ui_apply_msg, m) != LV_RESULT_OK) {
        printf("[UI] 界面投递失败，丢掉这次更新\n");
        free(m->reply);
        free(m);
    }
}
```
