typedef struct {
    int   status;   /* 状态栏，-1 = 这次不改 */
    int   face;     /* 表情，-1 = 这次不改 */
    char *reply;    /* 对话区文字，NULL = 不改（回调里 free） */
} ui_msg_t;

static void ui_apply_msg(void *arg)
{
    ui_msg_t *m = (ui_msg_t *)arg;

    if (m->status >= 0) {
        robot_ui_set_status((robot_status_t)m->status);
    }
    if (m->face >= 0) {
        robot_ui_set_face((robot_face_t)m->face);
    }
    if (m->reply != NULL) {
        robot_ui_set_ai_reply(m->reply);
    }

    free(m->reply);
    free(m);
}

static char *ui_strdup(const char *s)
{
    char *p;

    if (s == NULL) {
        return NULL;
    }

    p = malloc(strlen(s) + 1);
    if (p != NULL) {
        strcpy(p, s);
    }

    return p;
}

/* 非 LVGL 线程用：投递一次"状态 + 表情 + 文字"更新 */
static void ui_post(int status, int face, const char *reply)
{
    ui_msg_t *m = malloc(sizeof(ui_msg_t));

    if (m == NULL) {
        return;
    }

    m->status = status;
    m->face   = face;
    m->reply  = ui_strdup(reply);

    if (lv_async_call(ui_apply_msg, m) != LV_RESULT_OK) {
        printf("[UI] 界面更新投递失败，丢弃一次\n");
        free(m->reply);
        free(m);
    }
}

/* 提醒弹窗 / 报警页 / 报错页：都是"建对象"，同样只能在 LVGL 线程做 */

typedef struct {
    char *a;        /* 标题 / 正文 */
    char *b;        /* 正文（提醒才有第二个参数） */
    int   kind;     /* 0=提醒 1=报警 2=关报警 3=报错 */
} ui_panel_msg_t;

static void ui_apply_panel(void *arg)
{
    ui_panel_msg_t *m = (ui_panel_msg_t *)arg;

    switch (m->kind) {
        case 0:  robot_ui_show_reminder(m->a, m->b); break;
        case 1:  robot_ui_show_alarm(m->a);          break;
        case 2:  robot_ui_close_alarm();             break;
        default: robot_ui_show_error(m->a, m->b);    break;
    }

    free(m->a);
    free(m->b);
    free(m);
}

static void ui_post_panel(int kind, const char *a, const char *b)
{
    ui_panel_msg_t *m = malloc(sizeof(ui_panel_msg_t));

    if (m == NULL) {
        return;
    }

    m->kind = kind;
    m->a    = ui_strdup(a);
    m->b    = ui_strdup(b);

    if (lv_async_call(ui_apply_panel, m) != LV_RESULT_OK) {
        printf("[UI] 弹窗投递失败，丢弃一次\n");
        free(m->a);
        free(m->b);
        free(m);
    }
}

/* 三个语义化入口，调用点读起来跟直接调 robot_ui_* 一样 */
static void ui_post_reminder(const char *title, const char *content) { ui_post_panel(0, title, content); }
static void ui_post_alarm(const char *content)                       { ui_post_panel(1, content, NULL); }
static void ui_post_close_alarm(void)                                { ui_post_panel(2, NULL, NULL); }
static void ui_post_error(const char *title, const char *content)     { ui_post_panel(3, title, content); }
