```c
/* ==================== 提醒到点：AI 语音播报（音量渐进 + 念两遍） ==================== */
/*
 * 为什么单开线程：voice_tts_speak() 是阻塞的 HTTPS（TLS + 云端合成，几百 ms 到几秒），
 * 而 reminder_fire_async 跑在 LVGL 线程里 —— 直接调会把界面冻住。
 *
 * 播报策略（用户要求"声量渐进放大、不要太突兀、念两遍"）：
 *   1. 把合成的 PCM 复制两份首尾拼起来（一次播放里念两遍，省掉一次播放线程调度）；
 *   2. 对整段乘一条**软件增益斜坡**：第 1 遍从 30% 线性升到 100%，第 2 遍保持 100%
 *      —— 这是"音量渐进"最稳的做法：不动硬件音量（播放中途改 DAC 音量要走
 *      另开 fd 的 ioctl，会打断正在播的这段）；
 *   3. 网络/合成失败就退回原来的三声"嘀"，别让提醒整个哑掉。
 */
#define REMINDER_TTS_BUF_BYTES   (16000 * 2 * 6)   /* 6 秒，够念一句话 */
#define REMINDER_GAIN_START      30                /* 起始增益 30% */
#define REMINDER_FADE_MS         1800              /* 从 30% 升到 100% 用多久 */

static void *reminder_announce_thread(void *arg)
{
    char *title = (char *)arg;
    char text[64];
    unsigned char *pcm;
    size_t pcm_len = 0;
    int16_t *twice;
    size_t frames;
    size_t i;
    size_t fade_frames;
    int ret;

    snprintf(text, sizeof(text), "该%s了", title);

    pcm = malloc(REMINDER_TTS_BUF_BYTES);
    if (pcm == NULL) { free(title); return NULL; }

    ret = voice_tts_speak(text, pcm, REMINDER_TTS_BUF_BYTES, &pcm_len);
    if (ret < 0 || pcm_len == 0) {
        printf("[Reminder] 播报合成失败(%d)，退回提示音\n", ret);
        free(pcm); free(title);
        return NULL;                      /* 调用方已响过提示音 */
    }

    /* 两遍拼在一起（念两遍） */
    twice = malloc(pcm_len * 2);
    if (twice == NULL) { free(pcm); free(title); return NULL; }
    memcpy(twice, pcm, pcm_len);
    memcpy((char *)twice + pcm_len, pcm, pcm_len);
    free(pcm);

    frames = (pcm_len * 2) / sizeof(int16_t);

    /* 增益斜坡：第 1 遍 30%→100%，第 2 遍 100% */
    fade_frames = (size_t)(16000L * REMINDER_FADE_MS / 1000);
    if (fade_frames > frames) fade_frames = frames;

    for (i = 0; i < fade_frames; i++) {
        int32_t g = REMINDER_GAIN_START + (int32_t)(100 - REMINDER_GAIN_START) * (int32_t)i / (int32_t)fade_frames;
        twice[i] = (int16_t)((int32_t)twice[i] * g / 100);
    }

    printf("[Reminder] 语音播报: \"%s\"（%.1f 秒 ×2，音量 %d%%→100%%）\n",
           text, pcm_len / 32000.0, REMINDER_GAIN_START);
    if (audio_play_start(&g_audio_ctx, twice, frames, NULL, NULL) < 0) {
        printf("[Reminder] 播报播放失败\n");
    }

    free(twice);
    free(title);
    return NULL;
}
